#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);int best=0,cur=0;
for(int i=0;i<n;++i){int x;scanf("%d",&x);cur=(x==1)?cur+1:0;best=max(best,cur);}
printf("%d\n",best);return 0;}

